WHO = {'column': [('elylsen', 121192), ('kivdmnor', 121192), ('bridgepy', 121512), ('muldccyeben', 121512), ('vathlddmicro', 121512), ('zemunor', 121704), ('loleythi', 0), ('eindmmnor', 121832)], 'bridge': [('kivdmdnor', 0), ('mudldnor', 121512), ('qudidcyeben', 122854), ('loleymedu', 123302), ('muldccyeben', 0), ('qudidcyeben', 124517), ('loleymedu', 125539), ('muldccyeben', 0)], 'tree': [('kivdmicro', 0), ('kivdmcaki', 122407), ('elel', 122407), ('muldcfools', 122662), ('kivdmicro', 0), ('muldcylsen', 0), ('muldcdnor', 124580), ('kivdmcaki', 0)], 'tower': [('eincelceli', 122151), ('bridgepy', 0), ('loleydsen', 122407), ('loleycyeben', 125028), ('einsof', 126625), ('vathldeyeben', 131739), ('eincelceli', 0), ('loleydsen', 133721)], 'manor': [('aprilfools', 122598), ('muldcdnor', 0), ('kivdmicro', 125922), ('muldcdnor', 0), ('elylsen', 126689), ('qudidmicro', 129567), ('eincelceli', 131101), ('shaicyeben', 132187)], 'temple': [('muldcfools', 0), ('muut', 126242), ('qudidcyeben', 128991)], 'inscription': [('aprilldmicro', 129823)], 'castle': [('bridgepy', 0)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW254(OracleReleaseRuntimeW400):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
